package com.example.evcharging.finance.reconciliation;
public final class ReconciliationMatcher {
 private ReconciliationMatcher(){} public record LocalFact(String paymentNo,String channelTradeNo,long amountFen,long refundFen,String status){} public record ChannelFact(String paymentNo,String channelTradeNo,long amountFen,long refundFen,String status){} public record Result(ReconciliationResultType type,long differenceAmountFen){}
 public static Result match(LocalFact l,ChannelFact c){if(l==null&&c==null)throw new IllegalArgumentException("both facts cannot be null");if(l==null)return new Result(ReconciliationResultType.CHANNEL_ONLY,c.amountFen()-c.refundFen());if(c==null)return new Result(ReconciliationResultType.LOCAL_ONLY,-(l.amountFen()-l.refundFen()));if(l.amountFen()!=c.amountFen())return new Result(ReconciliationResultType.AMOUNT_MISMATCH,c.amountFen()-l.amountFen());if(l.refundFen()!=c.refundFen())return new Result(ReconciliationResultType.REFUND_MISMATCH,c.refundFen()-l.refundFen());if(!norm(l.status()).equals(norm(c.status())))return new Result(ReconciliationResultType.STATUS_MISMATCH,0);return new Result(ReconciliationResultType.MATCH,0);} private static String norm(String s){return s==null?"":s.trim().toUpperCase();}
}
